package com.paytrace.simulator; import com.paytrace.provider.ProviderFaultMode; public enum Scenario { HAPPY_PAYMENT, TIMEOUT_BEFORE_PROVIDER_PROCESSING, TIMEOUT_AFTER_PROVIDER_CAPTURE, DUPLICATE_CLIENT_RETRY, CONCURRENT_DUPLICATE_REQUESTS, DUPLICATE_WEBHOOK, OUT_OF_ORDER_WEBHOOK, MISSING_WEBHOOK, LEDGER_WRITE_FAILURE, PROVIDER_LEDGER_MISMATCH, DUPLICATE_PROVIDER_CAPTURE, REFUND_TIMEOUT, OVER_REFUND_ATTEMPT, MISSING_SETTLEMENT, LEDGER_IMBALANCE, SAFE_INTERNAL_RETRY; public ProviderFaultMode fault(){return switch(this){case TIMEOUT_BEFORE_PROVIDER_PROCESSING->ProviderFaultMode.TIMEOUT_BEFORE_PROCESSING;case TIMEOUT_AFTER_PROVIDER_CAPTURE->ProviderFaultMode.TIMEOUT_AFTER_CAPTURE;case REFUND_TIMEOUT->ProviderFaultMode.REFUND_TIMEOUT;default->ProviderFaultMode.NORMAL;};} }
